SELECT game_id AS "gameId", phase_id AS "phaseId", trigger_type_id AS "triggerTypeId", sequence_id AS "sequenceId", change_revision AS "changeRevision", updated_at AS "updatedAt" FROM public.ability_phase_effect_sequences WHERE game_id = #{gameId}
AND phase_id = #{phaseId}
AND sequence_id = #{sequenceId}
ORDER BY phase_id, trigger_type_id, sequence_id

 SELECT
game_id AS "gameId",
phase_id AS "phaseId",
trigger_type_id AS "triggerTypeId",
sequence_id AS "sequenceId",
change_revision AS "changeRevision",
updated_at AS "updatedAt"
 FROM public.ability_phase_effect_sequences
 WHERE game_id = #{gameId}
   AND phase_id = #{phaseId}
   AND trigger_type_id = #{triggerTypeId}
   AND sequence_id = #{sequenceId}
